  const before=await current('/price-rules',baseRule.record.id);await q('PUT','/price-rules/'+baseRule.record.id,{...baseRule.input,revision:before.revision,amountCents:1},403);assert.deepEqual(await current('/price-rules',baseRule.record.id),before);
