 await test('A blocked effective higher-priority override cannot silently fall back to a lower price',async()=>{
  const lowPolicy=await create('/approval-policies',policyInput({quorum:1})),highPolicy=await create('/approval-policies',policyInput({quorum:1}));
  const low=await create('/price-rules',ruleInput(list.record,lowPolicy.record,{sku:'BLOCKED-OVERRIDE',priority:1,amountCents:1000}));low.record=await approve(low.record,[reviewer1]);low.record=(await action('/activate',low.record)).record;
  const high=await create('/price-rules',ruleInput(list.record,highPolicy.record,{sku:'BLOCKED-OVERRIDE',priority:50,amountCents:5000}));high.record=await approve(high.record,[reviewer2]);high.record=(await action('/activate',high.record)).record;
  assert.equal((await quote(quoteInput({sku:'BLOCKED-OVERRIDE',priceListId:list.record.id}))).resolution.decision.resolvedPrice.amountCents,5000);
  try{reviewers=[actor,reviewer1];const revoked=await quote(quoteInput({sku:'BLOCKED-OVERRIDE',priceListId:list.record.id}));assert.equal(revoked.resolution.status,'source_changed');assert.equal(revoked.resolution.decision,null);}finally{reviewers=[actor,reviewer1,reviewer2];}
  await update('/approval-policies',highPolicy.input,highPolicy.record,{maximumAuthorizationSeconds:120});const changed=await quote(quoteInput({sku:'BLOCKED-OVERRIDE',priceListId:list.record.id}));assert.equal(changed.resolution.status,'source_changed');assert.equal(changed.resolution.decision,null);
 });
