  const preview=resolutionOf(await q('POST','/resolution-preview',{subjectKind:'catalog',catalogSubjectId:known.subject.id,priceListId:list.record.id,currency:'USD',quantity:1}));assert.equal(preview.status,'source_changed');assert.equal(preview.decision,null);
