  try{reviewers=[actor,reviewer2];const overview=(await listing('/quote-overview')).find(r=>r.id===original.id);assert(overview);assert.equal(overview.authorizationStatus,'source_changed');assert.equal(overview.decisionAvailable,false);assert.equal(overview.resolution.decision,null);assert.deepEqual(overview.originalResolution,before);}finally{reviewers=[actor,reviewer1,reviewer2];}
  assert.deepEqual((await current('/quote-jobs',original.id)).resolution,before);assert.deepEqual((await pool.query('SELECT * FROM pricing_decisions WHERE job_id=$1',[original.id])).rows,decisionRows);assert.deepEqual((await pool.query('SELECT * FROM pricing_history WHERE record_id=$1 ORDER BY id',[original.id])).rows,historyRows);
