  const expiringPolicy=await create('/approval-policies',policyInput({reviewRequired:false,quorum:0,separationOfDuties:false,maximumAuthorizationSeconds:1})),rule=await create('/price-rules',ruleInput(list.record,expiringPolicy.record,{sku:'EXPIRING-OVERVIEW'}));rule.record=(await action('/activate',rule.record)).record;const fresh=await quote(quoteInput({sku:'EXPIRING-OVERVIEW',priceListId:list.record.id}));assert.equal(fresh.resolution.status,'resolved');await delay(1250);const expired=(await listing('/quote-overview')).find(r=>r.id===fresh.record.id);assert.equal(expired.authorizationStatus,'expired');assert.equal(expired.decisionAvailable,false);assert.deepEqual(expired.originalResolution,fresh.resolution);assert.deepEqual((await current('/quote-jobs',fresh.record.id)).resolution,fresh.resolution);const filtered=await q('GET','/quote-overview?q=EXPIRING-OVERVIEW&status='+encodeURIComponent('authorization:expired')+'&limit=1');assert.equal(filtered.records.length,1);assert.equal(filtered.records[0].id,fresh.record.id);assert.equal((await q('GET','/quote-overview?q=EXPIRING-OVERVIEW&status=resolved')).records.length,0);assert.equal((await q('GET','/resolution-history?q=EXPIRING-OVERVIEW&status=resolved')).records[0].id,fresh.record.id);assert.equal((await q('GET','/resolution-history?q=EXPIRING-OVERVIEW&status=source_changed')).records.length,0);
